import backtrader as bt


class Strategy(bt.Strategy):
    params = (
        ('sma_period', 20),
        ('stop_pct', 0.0),
    )

    def __init__(self):
        self.accumdist = bt.indicators.AccumulationDistribution(self.data)
        self.sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_period
        )
        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            if order == self.order:
                self.order = None

            if order == self.stop_order:
                self.stop_order = None

            if order.status == order.Completed and order.isbuy() and not self.position:
                pass

            if (
                order.status == order.Completed
                and order == self.order
                and self.p.stop_pct > 0
            ):
                if order.isbuy() and self.position.size > 0:
                    self.stop_order = self.sell(
                        exectype=bt.Order.Stop,
                        price=order.executed.price * (1.0 - self.p.stop_pct),
                    )
                elif order.issell() and self.position.size < 0:
                    self.stop_order = self.buy(
                        exectype=bt.Order.Stop,
                        price=order.executed.price * (1.0 + self.p.stop_pct),
                    )

    def next(self):
        if self.order:
            return

        if self.position.size > 0:
            if self.accumdist[0] <= self.accumdist[-1]:
                if self.stop_order:
                    self.cancel(self.stop_order)
                self.order = self.close()
            return

        if self.position.size < 0:
            if self.accumdist[0] >= self.accumdist[-1]:
                if self.stop_order:
                    self.cancel(self.stop_order)
                self.order = self.close()
            return

        if self.data.close[0] > self.sma[0] and self.accumdist[0] > self.accumdist[-1]:
            self.order = self.buy()
        elif self.data.close[0] < self.sma[0] and self.accumdist[0] < self.accumdist[-1]:
            self.order = self.sell()
